python3 -c "
import json
from pathlib import Path
g = json.loads(Path('graphify-out/graph.json').read_text())
nodes={n['id']:n for n in g['nodes']}
# find the .Len() node under internal/version
target=None
for n in g['nodes']:
    if n.get('label')=='.Len()' and (n.get('source_file') or '').startswith('internal/version'):
        target=n['id']; print('node:',n)
# list caller source files
cs=set()
for e in g['links']:
    if e.get('relation') in ('calls','indirect_call') and e['target']==target:
        s=nodes.get(e['source'],{})
        cs.add(s.get('source_file'))
print('distinct caller files:', len(cs))
for f in sorted(x for x in cs if x)[:30]:
    print('  ',f)
"

